"""Build an offline, complete asset and spatial-design browser from shipped data."""
from pathlib import Path
import json,hashlib
ROOT=Path(__file__).resolve().parents[2]
def read(name):return json.loads((ROOT/'game/data'/name).read_text(encoding='utf-8'))
def main():
    balance=read('balance-prototype.json');assets=read('assets.json')['assets'];factions=read('factions.json');maps=read('maps.json')['maps']
    provenance={r['id']:r for filename in ['world-art-provenance.json','world-support-provenance.json'] for r in read(filename)['records']}
    entries=[]
    for uid,source in provenance.items():
        meta=assets[uid];unit=balance['units'].get(uid,{})
        entries.append(dict(id=uid,faction=uid.split('.')[1],name=unit.get('name',uid),category=meta['category'],path='../../game/'+meta['path'].removeprefix('res://'),source='../../'+source['source'],role=unit.get('role',''),gold=unit.get('gold'),hp=unit.get('hp'),damage=unit.get('damage'),range=unit.get('range'),hint=unit.get('hint',''),status=meta['status']))
    data={'entries':entries,'factions':factions['factions'],'maps':maps}
    template='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>纸上兵戈 · 素材与地图库</title>
<style>
@font-face{font-family:Paper;src:url('../../game/assets/fonts/NotoSansSC.ttf')}*{box-sizing:border-box}body{margin:0;background:#e8deca;color:#343332;font-family:Paper,system-ui,sans-serif;line-height:1.6}main{max-width:1480px;margin:auto;padding:32px}h1{font-size:38px;margin:0;color:#b74532}header p{max-width:950px}nav,.filters{display:flex;gap:16px;flex-wrap:wrap;margin:24px 0}button,select,input{font:inherit;padding:12px 18px;border:1px solid #a7967e;border-radius:4px;background:#f3ebdd;color:#343332;min-height:48px}button{cursor:pointer}button:hover,button[aria-pressed=true]{background:#cbb99b;border-color:#b74532}button:focus-visible,select:focus-visible,input:focus-visible,a:focus-visible{outline:3px solid #397e9e;outline-offset:3px}input{flex:1;min-width:220px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(245px,1fr));gap:20px}.card{background:#f3ebdd;border:1px solid #baa994;padding:16px;overflow:hidden}.card img{width:100%;height:235px;object-fit:contain;background:#d8d4c9}.card h2{font-size:20px;line-height:1.4;margin:12px 0 4px}.card p{font-size:14px;margin:8px 0}.id{font-family:monospace;font-size:12px;color:#655b4c;overflow-wrap:anywhere}a{color:#215d69}.map{width:100%;min-height:220px;background:#ded2bc;border:1px solid #baa994}.map-panel{background:#f3ebdd;padding:24px;border:1px solid #baa994}table{width:100%;border-collapse:collapse;margin:20px 0}th,td{padding:10px;border-bottom:1px solid #cbb99b;text-align:left}#map-description{max-width:1100px}footer{margin-top:40px;font-size:14px}small{display:block;color:#655b4c}
@media(max-width:650px){main{padding:20px}h1{font-size:28px}.grid{grid-template-columns:1fr}table{font-size:13px}td,th{padding:6px}.filters>*{width:100%}}
</style><main><header><h1>纸上兵戈</h1><p>400 种作战兵、10 名运金工、十院统帅与设施、七张新增地区背景。图片由指定 Sub2 路线生成，加工到 Godot 实际运行库；工人与召唤物另计。地图页读取全部 200 张实际路径定义。</p></header><nav aria-label="资料类型"><button id="asset-tab" aria-pressed="true">素材库 · 487 项新增素材</button><button id="map-tab" aria-pressed="false">地图库 · 200 张</button></nav>
<section id="asset-section"><div class="filters"><label>阵营 <select id="faction"></select></label><label>用途 <select id="category"><option value="all">全部</option><option value="unit">兵种与工人</option><option value="portrait">统帅</option><option value="building">设施</option><option value="prop">环境与道具</option><option value="background">地区背景</option></select></label><input id="search" type="search" aria-label="搜索素材名称、职责或能力" placeholder="搜索名称、职责、能力"><button id="reset">清除筛选</button></div><p id="count" role="status"></p><div class="grid" id="cards"></div></section>
<section id="map-section" hidden><div class="filters"><label>实际地图 <select id="map-choice"></select></label><button id="prev-map">上一张</button><button id="next-map">下一张</button></div><div class="map-panel"><h2 id="map-title"></h2><div id="map-svg"></div><p id="map-description"></p><p id="map-region"></p><small>青方与赤方各有独立路标选择；金点是矿位，方框是施工位。道路高度参与二维位置，不附加高地伤害。</small><table><thead><tr><th>矿点</th><th>所属</th><th>位置</th><th>同采容量</th><th>额外载荷</th></tr></thead><tbody id="mines"></tbody></table><a id="map-doc">打开本图完整空间设计稿</a></div></section>
<footer>权威参数：game/data。来源散列：world-art-provenance.json 与 world-support-provenance.json。资产文件与动作分件通过技术检查，源图审图和游戏内检查另有记录。旧 1.0 素材库保留作历史参考。<br>本浏览页是离线资料工具，正式游戏为 Godot Windows / Android 程序。</footer></main>
<script>const DATA=__DATA__;
const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
for(const f of DATA.factions){const o=el('option',f.name);o.value=f.id;$('faction').append(o)}
function assets(){const f=$('faction').value,c=$('category').value,q=$('search').value.trim().toLowerCase();const rows=DATA.entries.filter(a=>a.faction===f&&(c==='all'||a.category===c)&&[a.id,a.name,a.role,a.hint].join(' ').toLowerCase().includes(q));$('count').textContent=DATA.factions.find(x=>x.id===f).name+' · '+rows.length+' 项符合筛选';$('cards').replaceChildren(...rows.map(a=>{const card=el('article',undefined,'card'),im=el('img');im.src=a.path;im.alt=a.name;im.loading='lazy';card.append(im,el('h2',a.name),el('div',a.id,'id'));if(a.gold!=null)card.append(el('p',`${a.gold} 金 · 生命 ${a.hp} · 伤害 ${a.damage} · 射程 ${a.range}`));if(a.hint)card.append(el('p',a.hint));const link=el('a','查看未裁切源图');link.href=a.source;link.target='_blank';link.rel='noopener';card.append(link);return card}))}
for(const id of ['faction','category','search'])$(id).addEventListener(id==='search'?'input':'change',assets);$('reset').onclick=()=>{$('category').value='all';$('search').value='';assets()};
const NS='http://www.w3.org/2000/svg';function svgEl(tag,attributes){const n=document.createElementNS(NS,tag);for(const [k,v]of Object.entries(attributes))n.setAttribute(k,v);return n}
for(const [i,m] of DATA.maps.entries()){const o=el('option',String(i+1).padStart(3,'0')+' · '+m.name);o.value=i;$('map-choice').append(o)}
function map(){const index=Number($('map-choice').value),m=DATA.maps[index],pts=m.edges.flatMap(e=>e.points),minY=Math.min(...pts.map(p=>p[1])),maxY=Math.max(...pts.map(p=>p[1])),point=p=>[50+p[0]/m.length*1100,50+(p[1]-minY)/Math.max(2,maxY-minY)*180];const svg=svgEl('svg',{viewBox:'0 0 1200 290',class:'map',role:'img','aria-label':m.name+'道路、矿位与施工位'});for(const e of m.edges)svg.append(svgEl('polyline',{points:e.points.map(p=>point(p).join(',')).join(' '),fill:'none',stroke:'#9b8768','stroke-width':7}));for(const n of m.nodes){const [x,y]=point(n.position);svg.append(svgEl('circle',{cx:x,cy:y,r:5,fill:'#343332'}))}for(const mine of m.mines){const [x,y]=point([mine.x,mine.y]);svg.append(svgEl('circle',{cx:x,cy:y,r:9,fill:'#b9964f',stroke:mine.owner===0?'#397e9e':'#b74532','stroke-width':3}));const text=svgEl('text',{x,y:y+27,'text-anchor':'middle','font-size':19,fill:'#343332'});text.textContent=mine.capacity+' 工';svg.append(text)}for(const site of m.build_sites){const [x,y]=point([site.x,site.y]);svg.append(svgEl('rect',{x:x-6,y:y-6,width:12,height:12,fill:'#f3ebdd',stroke:site.owner===0?'#397e9e':'#b74532','stroke-width':3}))}$('map-svg').replaceChildren(svg);$('map-title').textContent=String(index+1).padStart(3,'0')+' · '+m.name;$('map-description').textContent=m.decision;$('map-region').textContent=m.regional_rule+`。全线最短 ${m.route_lengths.shortest.toFixed(2)}，最长 ${m.route_lengths.longest.toFixed(2)} 世界距离。`;$('mines').replaceChildren(...m.mines.map(v=>{const tr=el('tr');for(const value of [v.id,v.owner===0?'我方':'敌方',`(${v.x.toFixed(2)}, ${v.y.toFixed(2)})`,v.capacity,v.cargo_bonus])tr.append(el('td',String(value)));return tr}));$('map-doc').href='../../docs/paper-warfront/world/maps/'+m.id+'.md';$('prev-map').disabled=index===0;$('next-map').disabled=index===199}
$('map-choice').onchange=map;for(const [id,step]of [['prev-map',-1],['next-map',1]])$(id).onclick=()=>{$('map-choice').value=Math.max(0,Math.min(199,Number($('map-choice').value)+step));map()};for(const [id,asset]of [['asset-tab',true],['map-tab',false]])$(id).onclick=()=>{$('asset-section').hidden=!asset;$('map-section').hidden=asset;$('asset-tab').setAttribute('aria-pressed',asset);$('map-tab').setAttribute('aria-pressed',!asset)};assets();map();
</script></html>'''
    destination=ROOT/'assets/paper-warfront/world-v2-gallery.html'
    destination.write_text(template.replace('__DATA__',json.dumps(data,ensure_ascii=False).replace('</','<\\/')),encoding='utf-8')
    files=set()
    for meta in assets.values():
        files.add(meta['path'])
        if meta.get('portrait'):files.add(meta['portrait'])
        files.update(meta.get('animation',{}).get('parts',{}).values())
    for f in factions['order']:files.add(f'res://assets/audio/music/music-{f}.wav')
    files.update(['res://assets/fonts/NotoSansSC.ttf','res://assets/fonts/NotoSerifSC.ttf'])
    inventory=[]
    for path in sorted(files):
        p=ROOT/'game'/path.removeprefix('res://');assert p.is_file()
        inventory.append({'path':path,'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
    (ROOT/'game/data/asset-inventory.json').write_text(json.dumps({'version':'2.0.0','files':inventory},indent=2)+'\n',encoding='utf-8')
    print('Offline gallery:',len(entries),'new assets;',len(maps),'actual maps. Runtime inventory:',len(inventory),'files.')
if __name__=='__main__':main()
